function motionSegment(name,a,b,width,color,offset=0){const vals=(key,i)=>[a[key][i]+offset,b[key][i]+offset,b[key][i]+offset,a[key][i]+offset,a[key][i]+offset].join(";");return `<line x1="${a[name[0]][0]+offset}" y1="${a[name[0]][1]+offset}" x2="${a[name[1]][0]+offset}" y2="${a[name[1]][1]+offset}" stroke="${color}" stroke-width="${width}" stroke-linecap="round">${[["x1",name[0],0],["y1",name[0],1],["x2",name[1],0],["y2",name[1],1]].map(([attr,key,i])=>`<animate attributeName="${attr}" values="${vals(key,i)}" keyTimes="0;.35;.5;.85;1" dur="4s" repeatCount="indefinite" begin="indefinite"/>`).join("")}</line>`}
function motionScene(scene){const soft='stroke="var(--mu)" stroke-width="4" fill="none" opacity=".6"';const bench=(x,y,w)=>`<path d="M${x} ${y}h${w}m-${w-8} 0v${212-y}m${w-16} -${212-y}v${212-y}" ${soft}/>`;return ({floor:"",rearbench:bench(229,150,62),step:bench(64,155,76),sidestep:bench(54,171,76),seat:bench(87,155,57),hipbench:bench(65,137,62),heelbench:bench(248,151,55),flatbench:bench(63,214,189),wall:`<path d="M125 45v167" ${soft}/>`,anklewall:`<path d="M60 50v162" ${soft}/>`,door:`<path d="M105 25v187m110-187v187M105 25h110" ${soft}/>`,highband:`<circle cx="89" cy="20" r="5" fill="var(--ac)"/><path d="M89 20L167 59" stroke="#efae64" stroke-width="2" stroke-dasharray="5 4"/>`,rowband:`<path d="M268 95L218 98" stroke="#efae64" stroke-width="3"/>`,faceband:`<path d="M35 70h60" stroke="#efae64" stroke-width="3"/>`,woodband:`<path d="M55 28h34" stroke="#efae64" stroke-width="3"/>`,pallof:`<path d="M37 88h45" stroke="#efae64" stroke-width="3"/><text x="30" y="75" fill="var(--mu)" font-size="9">Bande</text>`,rotationband:"",kickband:"",passband:"",loopband:"",barshoulder:"",hamstrap:"",row:""})[scene]||""}
function motionDiagram(k){const m=TRIVEO_MOTIONS[k];if(!m)return "";const e=E[k],a=m.a,b=m.b,segments=[["hip","kneeR",8,"var(--fg)"],["kneeR","footR",8,"var(--fg)"],["shoulder","elbowR",7,"var(--fg)"],["elbowR","handR",7,"var(--fg)"],["hip","shoulder",19,"var(--ac)"],["hip","kneeL",9,"var(--tx)"],["kneeL","footL",8,"var(--tx)"],["shoulder","elbowL",8,"var(--tx)"],["elbowL","handL",7,"var(--tx)"],["head","shoulder",7,"var(--ac)"]];const circle=(key,r,color)=>`<circle cx="${a[key][0]}" cy="${a[key][1]}" r="${r}" fill="${color}"><animate attributeName="cx" values="${[a[key][0],b[key][0],b[key][0],a[key][0],a[key][0]].join(";")}" keyTimes="0;.35;.5;.85;1" dur="4s" repeatCount="indefinite" begin="indefinite"/><animate attributeName="cy" values="${[a[key][1],b[key][1],b[key][1],a[key][1],a[key][1]].join(";")}" keyTimes="0;.35;.5;.85;1" dur="4s" repeatCount="indefinite" begin="indefinite"/></circle>`;let accessory="";if(m.scene==="barshoulder")accessory=motionSegment(["handL","handR"],a,b,5,"#efae64");if(m.scene==="loopband")accessory=motionSegment(["kneeL","kneeR"],a,b,5,"#efae64");if(m.scene==="rotationband"||m.scene==="passband")accessory=motionSegment(["handL","handR"],a,b,3,"#efae64");if(m.scene==="hamstrap")accessory=motionSegment(["footL","handL"],a,b,2,"#efae64");if(m.scene==="kickband")accessory=motionSegment(["handR","footR"],a,b,2,"#efae64");return `<section class="motion-box st" data-exercise="${k}" data-duration="${m.duration}" data-speed="1" data-running="0"><div class="row"><h3>Mouvement en boucle</h3><span class="tg">Schéma animé</span></div><svg class="motion-svg" viewBox="0 0 320 244" role="img" aria-label="Schéma du mouvement : ${esc(e.n)}"><title>${esc(e.n)} — ${esc(m.view)}</title><desc>${esc(m.note)} Les proportions, les charges et la perspective sont simplifiées.</desc><path d="M18 214H302" stroke="var(--ln)" stroke-width="2"/>${motionScene(m.scene)}${segments.map(([p,q,w,c])=>motionSegment([p,q],a,b,w,c)).join("")}${circle("head",12,"var(--tx)")}${accessory}<text x="160" y="237" text-anchor="middle" fill="var(--mu)" font-size="10">${esc(m.view)}</text></svg><div class="wr"><button class="btn pri" onclick="toggleMotion(this)" aria-pressed="false">Animer le mouvement</button><button class="btn sec" onclick="slowMotion(this)" aria-pressed="false">Vitesse lente</button></div><p class="mu motion-status" aria-live="polite">Prêt · lecture en boucle au toucher</p><p>${esc(m.note)}</p><p class="mu">Repère visuel simplifié. Pour un maintien, l’animation montre surtout l’installation : tiens ensuite la durée de ta séance. Consulte les consignes pour les appuis, la charge et les côtés à travailler.</p></section>`}
function startMotion(box){const svg=box.querySelector("svg");svg.unpauseAnimations();box.querySelectorAll("animate").forEach(a=>{a.setAttribute("dur",Number(box.dataset.duration)/Number(box.dataset.speed)+"s");a.beginElement()});box.dataset.started="1"}
function toggleMotion(button){const box=button.closest(".motion-box"),svg=box.querySelector("svg"),status=box.querySelector(".motion-status");if(box.dataset.running==="1"){svg.pauseAnimations();box.dataset.running="0";button.textContent="Reprendre";button.setAttribute("aria-pressed","false");status.textContent="En pause"}else{if(!box.dataset.started)startMotion(box);else svg.unpauseAnimations();box.dataset.running="1";button.textContent="Pause";button.setAttribute("aria-pressed","true");status.textContent="Lecture en boucle · "+(box.dataset.speed==="0.5"?"vitesse lente":"vitesse normale")}}
function slowMotion(button){const box=button.closest(".motion-box"),wasRunning=box.dataset.running==="1";box.dataset.speed=box.dataset.speed==="0.5"?"1":"0.5";button.setAttribute("aria-pressed",box.dataset.speed==="0.5"?"true":"false");button.textContent=box.dataset.speed==="0.5"?"Vitesse normale":"Vitesse lente";if(box.dataset.started){startMotion(box);if(!wasRunning)box.querySelector("svg").pauseAnimations()}box.querySelector(".motion-status").textContent=(wasRunning?"Lecture en boucle":"Prêt / en pause")+" · "+(box.dataset.speed==="0.5"?"vitesse lente":"vitesse normale")}
